`timescale 1ns/1ps
module tb_l5_q128_rope_gqa;
 logic clk;/* verilator lint_off SYNCASYNCNET */logic rst_n;/* verilator lint_on SYNCASYNCNET */integer cycles,rope_cycles,gqa_cycles;
 logic riv,rir,rov,ror;logic[31:0]ra,rb,rc,rs,roa,rob;logic[4:0]rf,rfor;logic[31:0]rac,rcc;
 fp32_rope_pair rope(.clk_i(clk),.rst_ni(rst_n),.in_valid_i(riv),.in_ready_o(rir),.even_i(ra),.odd_i(rb),.cos_i(rc),.sin_i(rs),.out_valid_o(rov),.out_ready_i(ror),.even_o(roa),.odd_o(rob),.exception_flags_o(rf),.accepted_pairs_o(rac),.completed_pairs_o(rcc));
 logic giv,gir,gov,gor;logic[1:0]gri,gro;logic gki,gko;logic[2:0]gci,gco;logic gli,glo;logic[15:0]gti,gto;logic[511:0]gdi,gdo;logic[3:0]gqh;logic gil;logic[31:0]gac,gcc,gic;
 qwen_gqa_multicast16 gqa(.clk_i(clk),.rst_ni(rst_n),.in_valid_i(giv),.in_ready_o(gir),.role_i(gri),.kv_head_i(gki),.head_chunk_i(gci),.last_i(gli),.tag_i(gti),.data_i(gdi),.out_valid_o(gov),.out_ready_i(gor),.role_o(gro),.query_head_o(gqh),.kv_head_o(gko),.head_chunk_o(gco),.last_o(glo),.tag_o(gto),.data_o(gdo),.illegal_o(gil),.accepted_inputs_o(gac),.completed_outputs_o(gcc),.illegal_inputs_o(gic));
 logic[31:0]iq[0:589823],ik[0:98303],iv[0:98303],cf[0:49151],eq[0:589823],ek[0:98303],ekg[0:589823],evg[0:589823];logic[63:0]hq,hk,hv;integer workload;string dir;
 always #5 clk=~clk;always@(posedge clk)if(!rst_n)cycles<=0;else cycles<=cycles+1;
 function automatic[63:0]hb(input[63:0]seed,input[49151:0]d);logic[63:0]h;begin h=seed;for(int i=0;i<1536;i++)h=(h^{32'd0,d[i*32+:32]})*64'h100000001b3;hb=h;end endfunction
 task automatic run_rope(input[49151:0]x,input integer heads,input integer pos,output[49151:0]y);integer st,base;begin st=cycles;y=0;for(int h=0;h<heads;h++)for(int i=0;i<64;i++)begin base=h*128;@(negedge clk);ra=x[(base+i)*32+:32];rb=x[(base+64+i)*32+:32];rc=cf[pos*128+2*i];rs=cf[pos*128+2*i+1];riv=1;do@(posedge clk);while(!rir);@(negedge clk);riv=0;do@(posedge clk);while(!(rov&&ror));@(negedge clk);y[(base+i)*32+:32]=roa;y[(base+64+i)*32+:32]=rob;rfor|=rf;end rope_cycles+=cycles-st;end endtask
 task automatic run_gqa(input[8191:0]x,input[1:0]role,input integer token,output[49151:0]y);integer st;begin st=cycles;y=0;for(int c=0;c<16;c++)begin @(negedge clk);gri=role;gki=c>=8;gci=c[2:0];gli=c[2:0]==3'd7;gti=token[15:0];gdi=x[c*512+:512];giv=1;do@(posedge clk);while(!gir);@(negedge clk);giv=0;for(int rep=0;rep<6;rep++)begin if(!gov||gil||int'(gqh)!=(c>=8?6:0)+rep)$fatal(1,"q128 gqa sideband");y[gqh*4096+gco*512+:512]=gdo;gor=1;@(posedge clk);@(negedge clk);gor=0;end end gqa_cycles+=cycles-st;end endtask
 initial begin logic[49151:0]q,qo,kg,vg;logic[8191:0]k,v,ko;clk=0;rst_n=0;cycles=0;rope_cycles=0;gqa_cycles=0;riv=0;ror=1;rfor=0;giv=0;gor=0;hq=64'hcbf29ce484222325;hk=hq;hv=hq;if(!$value$plusargs("WORKLOAD=%d",workload))workload=128;if(workload!=128&&workload!=384)$fatal(1,"bad workload");dir=$sformatf("work/results/l5_q%0d_rope_gqa/vectors",workload);
  $readmemh({dir,"/q_input.memh"},iq);$readmemh({dir,"/k_input.memh"},ik);$readmemh({dir,"/v_input.memh"},iv);$readmemh({dir,"/coeff.memh"},cf);$readmemh({dir,"/q_rope.memh"},eq);$readmemh({dir,"/k_rope.memh"},ek);$readmemh({dir,"/k_gqa.memh"},ekg);$readmemh({dir,"/v_gqa.memh"},evg);repeat(3)@(posedge clk);rst_n=1;
  for(int t=0;t<workload;t++)begin for(int i=0;i<1536;i++)q[i*32+:32]=iq[t*1536+i];for(int i=0;i<256;i++)begin k[i*32+:32]=ik[t*256+i];v[i*32+:32]=iv[t*256+i];end run_rope(q,12,t,qo);run_rope({40960'd0,k},2,t,kg);ko=kg[8191:0];for(int i=0;i<1536;i++)if(qo[i*32+:32]!==eq[t*1536+i])$fatal(1,"q rope t=%0d i=%0d",t,i);for(int i=0;i<256;i++)if(ko[i*32+:32]!==ek[t*256+i])$fatal(1,"k rope");run_gqa(ko,1,t,kg);run_gqa(v,2,t,vg);for(int i=0;i<1536;i++)begin if(kg[i*32+:32]!==ekg[t*1536+i])$fatal(1,"kgqa");if(vg[i*32+:32]!==evg[t*1536+i])$fatal(1,"vgqa");end hq=hb(hq,qo);hk=hb(hk,kg);hv=hb(hv,vg);end
  if(rac!=workload*896||rcc!=workload*896||gac!=workload*32||gcc!=workload*192||gic!=0||rfor[4:1]!=0)$fatal(1,"prefill rope counters");$display("L5_Q_PREFILL_ROPE_GQA_PASS workload=%0d rope_pairs=%0d gqa_inputs=%0d gqa_outputs=%0d total_cycles=%0d rope_cycles=%0d gqa_cycles=%0d q_fnv64=%016h k_fnv64=%016h v_fnv64=%016h",workload,workload*896,workload*32,workload*192,cycles,rope_cycles,gqa_cycles,hq,hk,hv);$finish;end
 initial begin repeat(1800000)@(posedge clk);$fatal(1,"prefill rope timeout");end
endmodule
